const norm = (s) => String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/đ/g, 'd').replace(/Đ/g, 'D').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();

const CATEGORY_ALIAS = {
  'sac nhanh': 'cu sac', 'sac': 'cu sac', 'cu sac': 'cu sac', 'dau sac': 'cu sac',
  'day sac': 'cap', 'cap sac': 'cap', 'cap': 'cap',
  'pin du phong': 'sac du phong', 'sac du phong': 'sac du phong', 'pin': 'sac du phong',
  'tai nghe bluetooth': 'tai nghe', 'tai nghe chup tai': 'tai nghe', 'tai nghe': 'tai nghe', 'tai phone': 'tai nghe',
  'loa': 'loa bluetooth', 'loa bluetooth': 'loa bluetooth',
  'op': 'op lung', 'op lung': 'op lung', 'cuong luc': 'kinh cuong luc', 'kinh cuong luc': 'kinh cuong luc',
  'dong ho': 'dong ho thong minh', 'dong ho thong minh': 'dong ho thong minh', 'vong deo tay': 'dong ho thong minh',
  'chuot': 'chuot', 'ban phim': 'ban phim', 'dien thoai': 'dien thoai',
};
const catKey = (c) => { const k = norm(c); return CATEGORY_ALIAS[k] ?? k; };

const view = (p) => ({
  sku: p.sku, name: p.name, brand: p.brand, category: p.category, price: p.price, stock: p.stock,
  colors: p.colors, warranty_months: p.warranty_months, specs: p.specs, compatible: p.compatible,
});

function search(query, limit = 3) {
  const q = norm(query);
  if (!q) return [];
  const qTokens = new Set(q.split(' '));
  const scored = [];
  for (const p of PRODUCTS) {
    let best = norm(p.sku) && (` ${q} `).includes(` ${norm(p.sku)} `) ? 3 : 0;
    for (const name of [p.name, ...p.aliases]) {
      const a = norm(name);
      if (!a) continue;
      if ((` ${q} `).includes(` ${a} `)) { best = Math.max(best, 1 + a.length / 100); continue; }
      const toks = a.split(' ');
      best = Math.max(best, toks.filter((t) => qTokens.has(t)).length / toks.length);
    }
    if (best >= 0.6) scored.push([best, p]);
  }
  scored.sort((x, y) => y[0] - x[0]);
  const strong = scored.filter((s) => s[0] >= 1);
  return (strong.length ? strong : scored).slice(0, limit).map((s) => s[1]);
}

function byBudget({ category, budget_min, budget_max, brand, limit = 3 }) {
  return PRODUCTS
    .filter((p) => !category || catKey(p.category) === catKey(category))
    .filter((p) => !brand || norm(p.brand) === norm(brand))
    .filter((p) => (budget_min == null || p.price >= budget_min) && (budget_max == null || p.price <= budget_max))
    .filter((p) => p.stock > 0)
    .sort((a, b) => b.price - a.price)
    .slice(0, limit || 3);
}

function accessories({ sku, device, category, limit = 3 }) {
  let dev = device ? norm(device) : null;
  if (!dev && sku) dev = (PRODUCTS.find((p) => p.sku === sku) || {}).device || null;
  if (!dev) {
    const found = search(device || sku || '', 1)[0];
    dev = found && found.device ? found.device : null;
  }
  if (!dev) return { device: null, products: [] };
  const fits = (p) => p.compatible.some((c) => dev === c || dev.startsWith(c + ' ') || dev.startsWith(c));
  const list = PRODUCTS
    .filter((p) => !p.device && fits(p))
    .filter((p) => !category || catKey(p.category) === catKey(category))
    .sort((a, b) => (b.stock > 0) - (a.stock > 0) || a.price - b.price)
    .slice(0, limit || 3);
  return { device: dev, products: list };
}

const calls = $input.first().json.calls || [];
const results = calls.map(({ tool, args = {} }) => {
  try {
    if (tool === 'danh_sach') return { tool, args, ok: true, products: PRODUCTS.map(view), error: null };
    if (tool === 'tra_san_pham') return { tool, args, ok: true, products: search(args.query).map(view), error: null };
    if (tool === 'tim_theo_ngan_sach') return { tool, args, ok: true, products: byBudget(args).map(view), error: null };
    if (tool === 'phu_kien_tuong_thich') {
      const r = accessories(args);
      return { tool, args, ok: true, device: r.device, products: r.products.map(view), error: null };
    }
    return { tool, args, ok: false, products: [], error: `tool lạ: ${tool}` };
  } catch (e) {
    return { tool, args, ok: false, products: [], error: e.message };
  }
});
return [{ json: { results, source: 'gia' } }];
